package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0)      // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0                                   // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string  // PIC ZZ,ZZ9.99 len=9
var WsNetEd string   // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

// file handling
var curDiscRec DiscRec
var inputFile *os.File
var scanner *bufio.Scanner

func isInputDone() bool { return WsEofFlag == "Y" }

func storeDecimal(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	totalDigits := intDigits + scale
	truncated := val.Truncate(int32(scale))
	scaled := truncated.Shift(int32(scale))
	scaledInt := scaled.Truncate(0).IntPart()
	modBase := int64(1)
	for i := 0; i < totalDigits; i++ {
		modBase *= 10
	}
	sign := int64(1)
	if scaledInt < 0 {
		sign = -1
		scaledInt = -scaledInt
	}
	modVal := scaledInt % modBase
	if sign < 0 {
		modVal = -modVal
	}
	return decimal.New(modVal, int32(-scale))
}

func formatEdited(val decimal.Decimal, picture string) string {
	picRunes := []rune(picture)
	n := len(picRunes)
	dotIdx := -1
	for i, r := range picRunes {
		if r == '.' {
			dotIdx = i
			break
		}
	}
	intSlotIndices := []int{}
	decSlotIndices := []int{}
	for i, r := range picRunes {
		if dotIdx >= 0 {
			if i < dotIdx && (r == 'Z' || r == '9') {
				intSlotIndices = append(intSlotIndices, i)
			}
			if i > dotIdx && (r == 'Z' || r == '9') {
				decSlotIndices = append(decSlotIndices, i)
			}
		} else {
			if r == 'Z' || r == '9' {
				intSlotIndices = append(intSlotIndices, i)
			}
		}
	}
	intSlots := len(intSlotIndices)
	decSlots := len(decSlotIndices)

	valAbs := val.Abs()
	valTrunc := valAbs.Truncate(int32(decSlots))
	intPart := valTrunc.Truncate(0)
	intPartInt := intPart.IntPart()

	modBaseInt := int64(1)
	for i := 0; i < intSlots; i++ {
		modBaseInt *= 10
	}
	if modBaseInt != 0 {
		intPartInt = intPartInt % modBaseInt
		if intPartInt < 0 {
			intPartInt = -intPartInt
		}
	}
	intDigits := make([]int, intSlots)
	tmp := intPartInt
	for i := intSlots - 1; i >= 0; i-- {
		intDigits[i] = int(tmp % 10)
		tmp /= 10
	}
	// fractional digits
	var fracInt int64
	if decSlots > 0 {
		fracDec := valTrunc.Sub(decimal.NewFromInt(intPart.IntPart()))
		fracScaled := fracDec.Shift(int32(decSlots))
		fracInt = fracScaled.Truncate(0).IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
	}
	decDigits := make([]int, decSlots)
	tmpFrac := fracInt
	for i := decSlots - 1; i >= 0; i-- {
		decDigits[i] = int(tmpFrac % 10)
		tmpFrac /= 10
	}
	firstNonZero := intSlots
	for i := 0; i < intSlots; i++ {
		if intDigits[i] != 0 {
			firstNonZero = i
			break
		}
	}
	result := make([]rune, n)
	for i, r := range picRunes {
		if r == 'Z' || r == '9' || r == '.' || r == ',' {
			result[i] = ' '
		} else {
			result[i] = r
		}
	}
	for idx, slotPos := range intSlotIndices {
		picChar := picRunes[slotPos]
		digit := intDigits[idx]
		if picChar == '9' {
			result[slotPos] = rune('0' + digit)
		} else {
			if idx < firstNonZero {
				result[slotPos] = ' '
			} else {
				result[slotPos] = rune('0' + digit)
			}
		}
	}
	for idx, slotPos := range decSlotIndices {
		digit := decDigits[idx]
		result[slotPos] = rune('0' + digit)
	}
	for i, r := range picRunes {
		if r == '.' {
			result[i] = '.'
		} else if r == ',' {
			leftVisible := false
			for _, sp := range intSlotIndices {
				if sp < i && result[sp] != ' ' {
					leftVisible = true
					break
				}
			}
			if leftVisible {
				result[i] = ','
			} else {
				result[i] = ' '
			}
		}
	}
	return string(result)
}

func parsePriceField(s string) decimal.Decimal {
	var b strings.Builder
	for _, c := range s {
		if c >= '0' && c <= '9' {
			b.WriteRune(c)
		} else {
			b.WriteRune('0')
		}
	}
	ds := b.String()
	if ds == "" {
		ds = "0"
	}
	n, _ := strconv.ParseInt(ds, 10, 64)
	return decimal.New(n, -2)
}

func parsePctField(s string) int64 {
	var b strings.Builder
	for _, c := range s {
		if c >= '0' && c <= '9' {
			b.WriteRune(c)
		} else {
			b.WriteRune('0')
		}
	}
	ds := b.String()
	if ds == "" {
		return 0
	}
	n, _ := strconv.ParseInt(ds, 10, 64)
	return n % 100
}

func parseDiscRec(line string) DiscRec {
	drItem := line[0:6]
	drPriceStr := line[6:13]
	drPctStr := line[13:15]
	return DiscRec{
		DrItem:  drItem,
		DrPrice: parsePriceField(drPriceStr),
		DrPct:   parsePctField(drPctStr),
	}
}

// Paragraph functions

func MainPara() {
	// OPEN INPUT DISC-FILE
	var err error
	inputFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner = bufio.NewScanner(inputFile)
	WsEofFlag = "N"
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE DISC-FILE
	if inputFile != nil {
		inputFile.Close()
	}
	SummaryPara()
}

func ReadPara() {
	if scanner != nil && scanner.Scan() {
		line := scanner.Text()
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		curDiscRec = parseDiscRec(line)
	} else {
		if scanner != nil {
			if err := scanner.Err(); err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	tmp := curDiscRec.DrPrice.Mul(decimal.NewFromInt(curDiscRec.DrPct)).Shift(-2)
	discountRounded := tmp.Round(2)
	WsDiscount = storeDecimal(discountRounded, 5, 2)
	netRaw := curDiscRec.DrPrice.Sub(WsDiscount)
	WsNet = storeDecimal(netRaw.Truncate(2), 5, 2)
	newTotal := WsTotalNet.Add(WsNet)
	WsTotalNet = storeDecimal(newTotal.Truncate(2), 8, 2)
	WsCount = (WsCount + 1) % 1000

	WsPriceEd = formatEdited(curDiscRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	pctStr := fmt.Sprintf("%02d", curDiscRec.DrPct%100)
	line := curDiscRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Fprintln(os.Stdout, line)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount%1000)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Fprintln(os.Stdout, line)
}

func main() {
	MainPara()
}
